// === Tab: mySketch ===
const p=7;
let q=3;
let d;
let r;
let basis=[];
let Shader;
function preload(){
  Shader=getShader(this._renderer);
}

function setup() {
	// if (windowHeight<windowWidth) {createCanvas(windowHeight,windowHeight,WEBGL);}
	// else {createCanvas(windowWidth,windowWidth,WEBGL);}
	createCanvas(834, 834, WEBGL);
	background(50);

	pixelDensity(1);
}

function draw() {
	//q=map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,3,4);
	basis=[];
	d=sqrt((1/tan(PI/q)-tan(PI/p))/(tan(PI/p)+1/tan(PI/q)));
	r=(1/d-d)/(2*sin(PI/q));
	let v=createVector((d+1/d)/2,tan(PI/p)*(d+1/d)/2);
	//console.log(v.mag()-r);
	for (let i=0;i<p;i++) {
		basis.push(v.copy());
		v.rotate(2*PI/p);
	}
	let data=[];
	for (let b of basis) {data.push(b.x,b.y);}
	shader(Shader);
	Shader.setUniform("basis",data);
	Shader.setUniform("r",r);
	//Shader.setUniform("seed",map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,0,1000000000,true));
  rect(0,0,width,height);
	noFill();
	strokeWeight(20);
	stroke(0);
	for (let b of basis) {ellipse(b.x*width/2,b.y*width/2,2*r*height/4);}
	fill(255);
}

function inverse(m,v) {
		u=p5.Vector.sub(v,m);
		u.setMag(r**2/u.mag()).add(m);
		return u;
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

function getShader(_renderer) {
	return new p5.Shader(_renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position = positionVec4;
		}
	`, `
		precision highp float;
		varying vec2 vTexCoord;
		uniform vec2 basis[${p}];
		uniform float r;
		void main() {
			vec2 u=vec2(vTexCoord.x*2.-1.,(1.-vTexCoord.y)*2.-1.);
			vec3 c=vec3(.2,.2,.2);
			for (int t=0;t<10;t++) {
				if (length(u)>1.) {/*c=vec3(.2,.2,.2);*/break;}
				int b=0;
				float ds=r*r+1.;
				for (int B=0;B<${p};B++) {
					float DS=(u.x-basis[B].x)*(u.x-basis[B].x)+(u.y-basis[B].y)*(u.y-basis[B].y);
					if (DS<ds) {ds=DS;b=B;}
				}
				/*if (u.y>0.) {b=int(floor(mod(acos(u.x/length(u))/(2.*3.1415926535)*7.+.5,7.)));} 
				else  {b=int(floor(mod((1.-acos(u.x/length(u))/(2.*3.1415926535))*7.+.5,7.)));}*/
				if (ds>r*r) {
					c=vec3(0.,(u.x+1.)-.7,(u.y+1.)-.7);
					c+=vec3(
						1./(1.+pow(158148434879843159164645468466.,(ds-r*r-(ds-r*r)*0.5)))
					);
					//if (ds-r*r<0.01) {
					//	c=vec3(0.,0.,0.);
					//}
					break;
				}
				//c=vec3(float(b)/7.);
				//break;
				for (int i=0;i<${p};i++) {
					if (i==b) {u=normalize(u-basis[i])*r*r/length(u-basis[i])+basis[i];}
				}
			}

			gl_FragColor=vec4(c,1.);
		}
	`);
}

